package org.retrobridge.galaxychat.s2;
import android.app.*;
import android.graphics.*;
import android.os.*;
import android.view.*;
import android.widget.*;
import java.io.*;
/** Local photo zoom and ordinary video/audio playback. */
public final class MediaActivity extends Activity {
 protected void onCreate(Bundle state){super.onCreate(state);String mime=getIntent().getType();getActionBar().setTitle(getIntent().getStringExtra("name"));getActionBar().setDisplayHomeAsUpEnabled(true);
  if(mime!=null&&mime.startsWith("image/")){try{InputStream in=getContentResolver().openInputStream(getIntent().getData());BitmapFactory.Options o=new BitmapFactory.Options();o.inJustDecodeBounds=true;BitmapFactory.decodeStream(in,null,o);in.close();o.inSampleSize=1;while(Math.max(o.outWidth,o.outHeight)/o.inSampleSize>1600)o.inSampleSize*=2;o.inJustDecodeBounds=false;o.inPreferredConfig=Bitmap.Config.RGB_565;in=getContentResolver().openInputStream(getIntent().getData());Bitmap b=BitmapFactory.decodeStream(in,null,o);in.close();if(b==null)throw new IOException();setContentView(new Zoom(b));}catch(Exception e){finish();Toast.makeText(this,"Picture could not be opened",Toast.LENGTH_LONG).show();}}
  else if(mime!=null&&mime.startsWith("text/")){try{InputStream in=getContentResolver().openInputStream(getIntent().getData());ByteArrayOutputStream out=new ByteArrayOutputStream();try{byte[] b=new byte[4096];for(int n;(n=in.read(b))!=-1;){if(out.size()+n>1024*1024)throw new IOException("Text preview is limited to 1 MB");out.write(b,0,n);}}finally{in.close();}ScrollView scroll=new ScrollView(this);TextView text=new TextView(this);text.setText(new String(out.toByteArray(),"UTF-8"));text.setTextSize(16);text.setTextIsSelectable(true);text.setPadding(16,16,16,16);scroll.addView(text);setContentView(scroll);}catch(Exception e){Toast.makeText(this,"Text file could not be opened",Toast.LENGTH_LONG).show();finish();}}
  else{VideoView video=new VideoView(this);setContentView(video);MediaController controls=new MediaController(this);controls.setAnchorView(video);video.setMediaController(controls);video.setOnErrorListener(new android.media.MediaPlayer.OnErrorListener(){public boolean onError(android.media.MediaPlayer p,int what,int extra){Toast.makeText(MediaActivity.this,"This video format cannot play on the S2",Toast.LENGTH_LONG).show();finish();return true;}});video.setVideoURI(getIntent().getData());video.setOnPreparedListener(new android.media.MediaPlayer.OnPreparedListener(){public void onPrepared(android.media.MediaPlayer p){p.start();}});}
 }
 public boolean onOptionsItemSelected(MenuItem i){if(i.getItemId()==android.R.id.home){finish();return true;}return super.onOptionsItemSelected(i);}
 private final class Zoom extends View {final Bitmap bitmap;final Matrix matrix=new Matrix();final Paint paint=new Paint(3);final ScaleGestureDetector scale;float x,y;Zoom(Bitmap b){super(MediaActivity.this);bitmap=b;setBackgroundColor(0xff111111);scale=new ScaleGestureDetector(MediaActivity.this,new ScaleGestureDetector.SimpleOnScaleGestureListener(){public boolean onScale(ScaleGestureDetector d){matrix.postScale(d.getScaleFactor(),d.getScaleFactor(),d.getFocusX(),d.getFocusY());invalidate();return true;}});}protected void onSizeChanged(int w,int h,int ow,int oh){matrix.setRectToRect(new RectF(0,0,bitmap.getWidth(),bitmap.getHeight()),new RectF(0,0,w,h),Matrix.ScaleToFit.CENTER);}protected void onDraw(Canvas c){c.drawBitmap(bitmap,matrix,paint);}public boolean onTouchEvent(android.view.MotionEvent e){scale.onTouchEvent(e);if(e.getAction()==0){x=e.getX();y=e.getY();}else if(e.getAction()==2&&!scale.isInProgress()){matrix.postTranslate(e.getX()-x,e.getY()-y);x=e.getX();y=e.getY();invalidate();}return true;}protected void onDetachedFromWindow(){super.onDetachedFromWindow();bitmap.recycle();}}
}
